! ============================================================
! VML 系统扩展库 — Fortran
!
! 使用示例:
!   call asm("SYSCALL 57")    ! 扬声器蜂鸣
!   call asm("SYSCALL 58")    ! 设置 RTC 实时时钟
!   call asm("SYSCALL 60")    ! 获取系统配置
! ============================================================

! ============================================================
! SYSCALL 57 — SpeakerBeep
! 通过 PC 扬声器发出指定频率和时长的声音
! 参数:
!   R0 = 频率 (Hz)
!   R1 = 时长 (毫秒)
! 返回值: 无
!
! Fortran 使用示例:
!   ! 发出 440Hz (A4 音符) 持续 500ms
!   call asm("STORE 440, R0")
!   call asm("STORE 500, R1")
!   call asm("SYSCALL 57")
! ============================================================

! ============================================================
! SYSCALL 58 — SetRTC
! 设置系统实时时钟
! 参数: R0 = Unix 时间戳 (秒, 自 1970-01-01)
! 返回: R0 = 0 成功, <0 不支持
!
! 注意:
!   - C# 运行时当前为 stub, 返回 SUCCESS
!   - C 运行时在 OS 模式下通过 settimeofday() 实现
!
! Fortran 使用示例:
!   ! 设置时间为 2025-01-01 00:00:00 UTC
!   ! Unix 时间戳 = 1735689600
!   call asm("STORE 1735689600, R0")
!   call asm("SYSCALL 58")
! ============================================================

! ============================================================
! SYSCALL 60 — GetConfig
! 获取系统配置地址或值
! 参数: R0 = 查询类型码
! 返回: R0 = 地址或值
!
! 系统相关查询码:
!   10 = CONFIG_VERSION  — 配置接口版本
!   11 = STACK_BASE      — 栈区起始地址
!   12 = STACK_SIZE      — 栈区大小
!   13 = HEAP_START      — 堆起始地址 (0x400)
!    7 = MEMORY_SIZE     — 总内存字节数
!
! Fortran 使用示例:
!   ! 获取总内存大小
!   call asm("STORE 7, R0")
!   call asm("SYSCALL 60")
!   ! 返回: R0 = 总内存字节数
!
!   ! 获取堆起始地址
!   call asm("STORE 13, R0")
!   call asm("SYSCALL 60")
!   ! 返回: R0 = 0x400
! ============================================================

! ============================================================
! 其他常用系统调用:
!
! SYSCALL 50 — Random (生成随机数)
!   返回: R0 = 随机整数 [0, int.MaxValue]
!
! SYSCALL 51 — Seed (设置随机种子)
!   参数: R0 = 种子值
!
! SYSCALL 52 — Sleep (暂停执行)
!   参数: R0 = 毫秒数 (最小 1ms)
!
! SYSCALL 53 — GetTick (获取运行毫秒数)
!   返回: R0 = 毫秒数 (自 VM 启动起)
!
! SYSCALL 54 — GetDateTime (获取 Unix 时间戳)
!   返回: R0 = Unix 时间戳 (秒)
!
! SYSCALL 55 — GetDateString (获取日期字符串)
!   返回: R0 = 日期字符串地址 ("YYYY-MM-DD\0")
!
! SYSCALL 56 — GetTimeString (获取时间字符串)
!   返回: R0 = 时间字符串地址 ("HH:mm:ss\0")
!
! SYSCALL 40 — Alloc (分配内存)
!   参数: R0 = 请求字节数
!   返回: R0 = 分配的内存地址
!
! SYSCALL 41 — Free (释放内存)
!   参数: R0 = 要释放的内存地址
! ============================================================
